    /**
     * Tests creating a new Contact.
     *
     * @return    Contact
     */
    public Contact testCreate() throws Throwable {
    Contact entity = null;

    LOGGER.info( "ContactTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Contact");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Contact" );

    try {
        entity = service.createContact( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getContactId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Contact with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Contact.
     *
     * @return    Contact
     */
    public Contact testRead() throws Throwable {
    LOGGER.info( "ContactTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Contact" );

    Contact entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Contact with primary key" );
    msg.append( theId );

    try {
        entity = service.getContact( new ContactFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getContactId();

        LOGGER.info( "-- Successfully found Contact " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Contact.
     *
     * @return    Contact
     */
    public Contact testUpdate() throws Throwable {
    LOGGER.info( "ContactTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Contact." );

    StringBuilder msg = new StringBuilder( "Failed to update a Contact : " );
    Contact entity = null;

    try {
        UpdateContactCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setContactId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Contact." );

        entity = service.updateContact( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Contact - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Contact.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "ContactTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Contact." );

    try {
        DeleteContactCommand deleteCommand = new DeleteContactCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Contact with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Contact with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Contacts.
     *
     * @return    Collection
     */
    public List<Contact> testGetAll() throws Throwable {
    LOGGER.info( "ContactTest:testGetAll() - Retrieving Collection of Contacts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Contact : " );
    List<Contact> collection  = null;

    try {
        // call the static get method on the ContactService
        collection = service.getAllContact();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Contact currEntity  = null;
            Iterator<Contact> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getContactId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

